+#[cfg(target_arch = "wasm32")]
+fn replace_event_source(slot: &EventSourceSlot, next: EventSource) {
+    let previous = slot
+        .lock()
+        .expect("event source slot poisoned")
+        .replace(SendWrapper::new(next));
+    if let Some(previous) = previous {
+        previous.take().close();
+    }
